// Moves the Better Auth tables generated by `auth generate` into Postgres schema "auth" (the CLI's own schemaName
// option only works with a live adapter, and @better-auth/oauth-provider's init needs its tables to exist first).
//   node scripts/auth-schema.mjs <generated.ts> <db/auth-schema.ts>
import { readFile, writeFile } from 'node:fs/promises';

const [src, dest] = process.argv.slice(2);
let s = await readFile(src, 'utf8');
if (!/\bpgTable\(/.test(s)) throw new Error('no pgTable( in input');
s = s.replace(/^\s*pgTable,\n/m, '  pgSchema,\n');
s = s.replace(/\bpgTable\(/g, 'authSchema.table(');
s = s.replace(/(\} from "drizzle-orm\/pg-core";\n)/, '$1\nexport const authSchema = pgSchema("auth");\n');
await writeFile(dest, `// Generated by \`npm run auth:schema\` (auth generate + scripts/auth-schema.mjs). Do not edit by hand.\n${s}`);
